# aeneid-094 (XII.311-440): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Aeneas saucius et sanatus'
PART = "Aeneas Wounded and Healed (XII.311–440)"
TITLE_EN = "Aeneas Wounded and Healed — Aeneid XII.311–440"
ABOUT = ("As the truce collapses, Aeneas, bareheaded and unarmed, tries to hold his own men back: the treaty is sworn, and the right to fight belongs to him alone. "
"While he is still speaking an arrow strikes him; no one ever learned whose hand shot it, and no one boasted of the wound. "
"When Turnus sees Aeneas leave the field his hopes blaze up. He mounts his chariot and storms through the Trojan ranks like Mars driving his horses over the plains of Thrace, or the north wind scattering the clouds, and kills as he goes: among others Eumedes, son of the spy Dolon, whom he mocks as he dies with the land of Italy he came to win, and Phegeus, who seizes the horses' heads and is beheaded. "
"Meanwhile Aeneas, bleeding and leaning on a spear, is brought back to the camp, raging and demanding that the wound be cut open so that he can return to the fight. "
"The old healer Iapyx, who long ago chose medicine over the gifts of prophecy and song that Apollo offered him, works in vain with forceps and herbs while the battle draws nearer. "
"Then Venus, hidden in a cloud, brings dittany from Cretan Ida and secretly steeps it in the water; Iapyx bathes the wound, the pain vanishes, the arrow drops out at a touch, and he cries that a god is at work. "
"Aeneas arms at once and, before going out, embraces Ascanius through his helmet: let the boy learn manhood and real effort from his father, good fortune from others, and remember Aeneas and Hector. "
"The wounding under truce and the healing by a god both have models in the Iliad, and the farewell to the boy recalls Hector with Astyanax and Sophocles' Ajax with his son.")

U = [
(312, 'vocabat:',
 "But dutiful Aeneas his right hand was stretching out, unarmed,\nwith head bared, and his men with a shout he was calling:",
 "But Aeneas, true to his duty, held out his right hand, unarmed, his head bare, and called to his men with a shout:",
 "A new paragraph in Greenough: the truce has broken down, and Aeneas tries to hold his own side back. 'At', 'but', the strong turn. 'pius Aeneas', his standing epithet, pointed here: he keeps faith while others break it. 'dextram… inermem', 'his unarmed right hand', framing the line, a sign of peace. 'tendebat… vocabat', imperfects, 'was stretching… was calling', the action in progress when the arrow comes. 'nudato capite', ablative absolute, 'head bared', without his helmet, to be recognised and to show he does not mean to fight. 'Aeneas', 'Ae-' one long syllable. Elision 'capit(e) atque'."),
(313, 'surgit?',
 "“Where are you rushing? Or what is this sudden discord that rises?",
 "“Where are you rushing? What is this sudden quarrel that springs up?",
 "Aeneas's speech runs to 317. 'Quo ruitis?', 'where are you rushing?', a question of reproach rather than of fact. '-ve', 'or', on 'quae', 'or what'. 'ista', 'that (of yours)', the pronoun of the person addressed, often with a touch of scorn. 'repens', 'sudden', an adjective with the force of an adverb. 'discordia surgit', 'strife rises', discord pictured as a power rearing its head. Elision 'Quaev(e) ista'."),
(315, 'soli;',
 "O hold in your angers! Struck already is the treaty, and all\nthe terms settled; to me is the right to join battle, to me alone;",
 "Oh, curb your anger! The treaty is already struck and all its terms are settled; the right to fight belongs to me, and to me alone;",
 "'O cohibete iras!', 'restrain your angers', the plural for the outbursts on every side. 'Ictum… foedus', 'the treaty (has been) struck', 'icere foedus', from the victim struck at the sacrifice; 'est' is understood, as with 'compositae (sunt) leges', 'the terms have been settled'. 'mihi ius concurrere soli', 'to me alone (is) the right to engage', a dative of possession, 'mihi… soli' framing the clause: under the treaty only Aeneas and Turnus may fight. 'Ictum iam': the i of 'iam' is consonantal, so there is no elision before it. Elision 'cohibet(e) iras'."),
(317, 'sacra.”',
 "me allow, and take away your fears; I the treaty will make\nfirm with my hand; Turnus these rites already owe to me.”",
 "leave it to me, and put away your fears; with my own hand I will make the treaty hold. These rites have already made Turnus mine.”",
 "'me sinite', 'let me (do it)'. 'auferte metus', 'take away (your) fears'. 'faxo', an old future of 'facio', 'I will make', kept in solemn and in everyday speech; with 'foedera… firma', 'I will make the treaty firm', the noun and its adjective split across the line. 'manu', 'by (my) hand', in the fight. 'Turnum debent haec iam mihi sacra', 'these rites already owe Turnus to me': by the sacrifice and the oath Turnus is pledged to meet him, as a victim is owed to the gods. Elisions 'sinit(e) atque', 'atqu(e) auferte'."),
(322, 'adtulerit:',
 "Amid these words, in the middle of such speaking,\nlook, upon the man, hissing on its wings, there glided an arrow,\nit is unknown by what hand sped, by what whirl driven home,\nwho such great glory to the Rutulians, chance was it or a god,\nhad brought:",
 "Even as he spoke these words, in the very middle of such speech, an arrow came hissing on its feathers and struck him, and no one knows what hand let it fly or what force drove it home, who brought the Rutulians such glory, whether chance or a god:",
 "'Has inter voces', 'among these words', the preposition set between adjective and noun, as again in 'media inter talia verba'; the doubled phrase marks the very moment. 'ecce', 'look!', the narrator's sudden turn. 'viro', dative with 'adlapsa est', 'glided to the man'; 'adlapsa' is Greenough's spelling of 'allapsa'. 'stridens alis', 'whirring with its wings', the feathers of the arrow. 'incertum (est)', 'it is uncertain', with indirect questions in the subjunctive: 'qua… manu', 'quo turbine', 'quis… adtulerit' ('attulerit'). 'casusne deusne', 'whether chance or a god', the double '-ne'; 'deus' is two syllables, de-us, not a diphthong. The model is Pandarus's arrow, which wounded Menelaus under truce in Iliad IV. Elisions 'medi(a) inter', 'sagitt(a) est', 'turbin(e) adacta'."),
(323, 'quisquam.',
 "suppressed was the distinguished glory of the deed,\nand no one vaunted himself on the wound of Aeneas.",
 "the fame of that remarkable deed was smothered, and no one ever boasted of having wounded Aeneas.",
 "The print has 'facti. nec', a full stop followed by a small letter, a misprint for 'facti, nec', corrected here: the two clauses make one sentence. 'pressa est', 'was pressed down, suppressed': no one claimed the shot. 'insignis gloria facti', 'the glory of the notable deed'; 'insignis' may go with 'gloria' or, as a genitive, with 'facti', with much the same sense. 'sese… iactavit', 'boasted himself, vaunted'; 'vulnere', ablative of cause, 'on account of the wound'. 'Aeneae', genitive, three syllables, Ae-ne-ae, the first a long diphthong. Elisions 'press(a) est', 'ses(e) Aeneae'."),
(325, 'ardet:',
 "Turnus, when Aeneas withdrawing from the column he saw,\nand the leaders thrown into confusion, with sudden hope, seething, blazes:",
 "When Turnus saw Aeneas leaving the field and the leaders in disarray, he blazed up, burning with sudden hope:",
 "'Turnus ut… vidit', 'when Turnus saw', 'ut' with the perfect indicative meaning 'as soon as', the subject set before the conjunction for emphasis. 'Aenean', Greek accusative, 'Ae-' one long syllable. 'cedentem ex agmine', 'withdrawing from the line', to have the arrow seen to. 'turbatos… duces', 'the captains thrown into confusion', the Trojan leaders. 'subita spe', 'with sudden hope', ablative of cause. 'fervidus ardet', 'hot, he burns', the adjective doubling the verb: Turnus at his most fiery. 'ardet', historic present, the tense of the narrative from here on. Elision 'cedent(em) ex'."),
(327, 'habenas.',
 "he demands his horses and arms together, and with a leap, proud,\nhe springs into the chariot and with his hands works the reins.",
 "He calls at once for his horses and his armour, leaps proudly up into his chariot and takes the reins in his hands.",
 "'poscit… simul', 'demands at the same moment', horses and arms together. 'saltu', 'with a leap'; 'superbus', 'proud', the adjective with the force of an adverb. 'emicat', 'flashes up, springs', a verb of sudden light used of a sudden movement. 'molitur habenas', 'works the reins', 'molior' suggesting effort and heaving: Turnus takes the reins himself. Elisions 'atqu(e) arma', 'curr(um) et'."),
(330, 'hastas.',
 "Many, of men, flying about, he gives brave bodies to Death,\nhalf-dead he rolls over many, or columns with his chariot\nhe tramples, or snatched-up spears at the fleeing he hurls.",
 "Racing over the field he gives many brave men's bodies to Death; many he sends rolling half-dead, or he crushes whole files beneath his chariot, or snatches up spears and hurls them at those who run.",
 "'Multa virum… fortia corpora', 'many brave bodies of men', 'virum' the old genitive plural (you have met it often). 'volitans', 'flying to and fro', a frequentative. 'dat… Leto', 'gives to Death', Death as a person. 'semineces', 'half-dead', from 'semi-' and 'nex'. 'volvit', 'rolls (in the dust)', sends sprawling. 'aut… aut', 'or… or', the threefold description. 'raptas… hastas', 'snatched-up spears', perhaps lying on the field, framing the line. 'fugientibus', dative, 'at those fleeing'. 'ingerit', 'heaps on, hurls'. No elisions."),
(333, 'equos;',
 "Such as when, beside the streams of cold Hebrus, aroused,\nblood-stained Mavors clangs on his shield and, his raging,\nwar stirring up, lets loose his horses;",
 "Just as when, by the streams of the icy Hebrus, blood-stained Mars is roused, beats upon his shield and, stirring up war, gives his maddened horses their head;",
 "A simile in the Homeric manner, 'Qualis… talis' (337): Turnus is like Mars driving his chariot. It is cut at the semicolon. 'Qualis… cum', 'such as when'. 'Hebri', the Hebrus, the great river of Thrace, Mars's own country; 'gelidi', 'icy', Thrace being the cold north to Greeks and Romans. 'Mavors', the old poetic name of Mars. 'concitus', 'roused'. 'clipeo increpat', 'makes a din on his shield', the signal for war. 'bella movens', 'stirring up wars'. 'immittit', 'lets go, sends at full speed'; 'furentis… equos', 'the raging horses', with Greenough's -is accusative plural, split across the line. The model is Ares setting out for Thrace with Terror in Iliad XIII. Elision 'clipe(o) increpat'."),
(336, 'aguntur:',
 "they, on the open plain,\nahead of the South Winds and the West Wind fly; groans, to its farthest, with the beat\nThrace, of their hooves; and around, the faces of black Terror\nand Wraths and Ambushes, the god's escort, are borne along:",
 "out on the open plain they fly faster than the South Winds and the West, the farthest reaches of Thrace groan under the pounding of their hooves, and round him race the faces of black Terror, and Wrath, and Ambush, the god's companions:",
 "'illi', the horses. 'aequore aperto', 'on the open level', 'aequor' used of a plain as well as of the sea. 'ante Notos Zephyrumque volant', 'they fly ahead of the South Winds and the West Wind', outrunning the winds, a Homeric boast for horses. 'gemit… Thraca', 'Thrace groans', 'ultima', 'to its farthest parts'; 'Thraca' is a Greek form of 'Thracia'. 'pulsu pedum', 'with the beat of feet', the hooves. 'atrae Formidinis ora', 'the faces of black Terror', with Wrath and Treachery as persons, like Homer's Deimos and Phobos, Ares' sons and companions. 'dei comitatus', 'the god's escort', in apposition. 'aguntur', 'are driven along' with him. Elisions 'ill(i) aequore', 'aequor(e) aperto', 'circumqu(e) atrae', 'Iraequ(e) Insidiaeque'."),
(340, 'harena.',
 "so Turnus his horses, eager, through the midst of battles,\nsteaming with sweat, drives hard, pitiably on the slain\nenemies trampling; scatters the swift hoof dews,\nbloody, and, with the sand mixed, the gore is trodden.",
 "so Turnus, eager, drives his horses, steaming with sweat, through the thick of the fighting, trampling cruelly on the enemies he has killed; the flying hooves spatter a bloody dew, and the gore is trodden into the sand.",
 "'talis', 'such', answering 'Qualis' in 331. 'alacer', 'eager, keen'. 'media inter proelia', the preposition between adjective and noun. 'fumantis sudore', 'steaming with sweat', Greenough's -is accusative, with 'equos'. 'quatit', 'shakes, drives hard', the horses jolting at the gallop. 'miserabile', neuter used as an adverb, 'pitiably'. 'caesis hostibus insultans', 'leaping on the slain enemy', a dative with a compound verb; the word also means 'mocking', and both senses are present. 'rores sanguineos', 'bloody dews', a striking metaphor for spattered blood. 'mixta… harena', 'with sand mixed in', framing the clause. Compare Achilles' horses trampling the dead in Iliad XX. Elisions 'medi(a) inter', 'rapid(a) ungula'."),
(345, 'ventos.',
 "And now to death both Sthenelus he gave and Thamyrus and Pholus,\nthis one meeting close, and this one, that one from afar; from afar the two\nsons of Imbrasus, Glaucus and Lades, whom Imbrasus himself\nhad reared in Lycia and with matching arms had equipped,\neither to join hand or on horseback to outstrip the winds.",
 "And now he had sent Sthenelus to his death, and Thamyrus, and Pholus, the first two hand to hand, the third from a distance; from a distance too the two sons of Imbrasus, Glaucus and Lades, whom Imbrasus himself had raised in Lycia and fitted out with matching armour, ready to fight hand to hand or to outrun the winds on horseback.",
 "A catalogue of victims, in the Homeric manner. 'neci… dedit', 'gave to death', 'nex' being violent death. '-que… -que… -que', 'both… and… and', giving a list. 'hunc… et hunc, illum', 'this one and this one, that one': 'congressus', 'meeting (them) at close quarters'; 'eminus', 'at a distance', with a thrown spear, repeated at once for the next pair. 'Imbrasidas', 'the sons of Imbrasus', a Greek patronymic in the accusative plural. 'Laden', Greek accusative of 'Lades'. 'Lycia', ablative of place, 'in Lycia', in Asia Minor, home of Troy's allies in Homer. 'paribus… armis', 'with matching arms'. 'vel conferre manum vel… praevertere', infinitives of purpose with 'ornaverat', 'equipped to fight hand to hand or to outrun'. Elisions 'ill(um) eminus', 'Glauc(um) atque', 'paribusqu(e) ornaverat'."),
(350, 'currus;',
 "In another part, into the midst of battle, Eumedes is borne,\nof ancient Dolon the offspring, renowned in war,\nby name his grandfather recalling, in spirit and hands his father,\nwho once, so that the camp of the Danaans as a spy he might approach,\ndared the chariot of Peleus's son as his reward to demand;",
 "Elsewhere Eumedes charges into the thick of the battle, son of Dolon of old and famous in war, who recalled his grandfather in his name and his father in courage and strength of hand: that Dolon who once, to go as a spy into the Greek camp, had dared to ask as his reward the chariot of Achilles;",
 "'Parte alia', 'in another part' of the field. 'Eumedes', a Greek name, 'Eu-' one syllable, the Greek diphthong. He is the son of Dolon, the Trojan spy of Iliad X, whose own father was called Eumedes: so he bears his grandfather's name ('nomine avum referens') and his father's daring ('animo manibusque parentem'). 'proles… praeclara', 'renowned offspring'. 'qui', Dolon. 'castra ut Danaum… adiret', 'so that he might go to the Greeks' camp', a purpose clause with 'ut' placed late; 'Danaum', old genitive plural. 'speculator', 'as a spy'. 'Pelidae… currus', 'the chariot of the son of Peleus', Achilles: in Homer Dolon asks Hector for Achilles' horses and chariot as his pay. 'ausus (est)'. Elisions 'Part(e) alia', 'medi(a) Eumedes', 'nomin(e) avum', 'castr(a) ut'."),
(352, 'Achillis.',
 "him the son of Tydeus with another, for such daring,\nrewarded, a price, and he aspires no more to the horses of Achilles.",
 "but for such daring the son of Tydeus paid him a different reward, and he no longer has his eyes on Achilles' horses.",
 "'illum', Dolon. 'Tydides', 'the son of Tydeus', Diomedes, who with Odysseus caught Dolon in Iliad X and killed him after questioning him. 'alio… pretio', 'with another price', split across the line, a grim joke: he got death for his pay. 'pro talibus ausis', 'for such daring deeds', 'ausum' a noun made from the participle. 'adfecit', 'visited (him) with', Greenough's spelling of 'affecit'. 'nec… adspirat', 'and he does not aspire to', present tense: he aims at them no longer; 'adspirat' ('aspirat') takes the dative 'equis'. No elisions."),
(353, 'aperto,',
 "Him, far off, when on the plain Turnus caught sight of, open,",
 "When Turnus caught sight of him far off across the open plain,",
 "The long period runs from 353 to 358 and is cut at the comma. 'Hunc', Eumedes, placed first as the object of the whole sentence. 'ut… prospexit', 'when he spied (him)', 'ut' with the perfect indicative. 'procul', 'far off'. 'campo… aperto', 'on the open plain', ablative of place without a preposition, framing Turnus and his verb. No elisions."),
(358, 'addit:',
 "first with a light javelin through the long void having followed him,\nhe halts the two-yoked horses and from the chariot leaps down, and\non the half-dead, fallen man comes down, and with foot on his neck\npressed, from his right hand the blade he wrenches, and in the deep\nthroat dyes it, flashing, and these words besides he adds:",
 "he first sent a light javelin after him across the long space between, then halted his pair of horses, leapt from the chariot, stood over the fallen man as he lay half-alive, planted his foot on his neck, wrenched the sword from his right hand, dyed the shining blade deep in his throat, and added these words besides:",
 "'ante… secutus', 'having first followed (him)', that is, struck him from afar: the javelin chased him through 'longum… inane', 'the long void', the empty air between. 'sistit equos biiugis', 'halts his two-yoked horses'; in 'biiugis' the second i is consonantal, bi-ju-gis. 'semianimi lapsoque', 'on the half-alive and fallen man', dative with 'supervenit', 'comes down upon'; 'semianimi' is four syllables, the i after 'semi' consonantal. 'pede collo impresso', ablative absolute, 'foot pressed on neck'. 'dextrae', dative of separation, 'from his right hand'. 'mucronem… fulgentem', 'the point, flashing': he kills him with his own sword. 'alto… iugulo', 'in the deep throat'. 'tinguit', Greenough's spelling of 'tingit'. Elisions 'mucron(em) extorquet', 'iugul(o) atque', 'atqu(e) haec'."),
(360, 'iacens:',
 "“Look, the fields, and, which in war, Trojan, you sought,\nHesperia, measure them lying there:",
 "“There, Trojan, are the fields and the Hesperia you came to win by war: measure them out as you lie;",
 "Turnus's taunt runs to 361. 'En', 'look!', 'there you have'. 'agros et… Hesperiam', 'the fields and Hesperia', the land of the west, Italy, promised to the Trojans; the relative clause 'quam bello… petisti', 'which you sought by war', comes before its noun. 'petisti' = 'petivisti'. 'Troiane', 'Trojan', said in scorn: Eumedes is a Trojan, like his father. 'metire iacens', 'measure (it) lying (there)', the imperative of the deponent 'metior': the land he sought is now the length of his own body. The i of 'iacens' is consonantal, so 'metire' does not elide before it. No elisions."),
(361, 'condunt.”',
 "these rewards those who me\nwith steel have dared to try carry off; so walls they found.”",
 "this is the prize they carry off who dare to try me with the sword; this is how they build their walls.”",
 "'haec praemia… ferunt', 'these rewards they carry off', the antecedent of 'qui' ('those who') left out. 'me ferro… temptare', 'to try me with the sword', to test me in arms. 'ausi (sunt)'. 'sic moenia condunt', 'thus they found their walls': the bitter joke turns on the Trojans' mission, to found a city in Italy, and offers them only a grave. Homer's warriors mock the fallen in the same way, as Patroclus mocks Cebriones' fall from his chariot in Iliad XVI. Elision 'ferr(o) ausi'."),
(364, 'Thymoeten.',
 "To him as companion Asbytes, with a hurled spear-point, he sends.\nAnd Chloreus, and Sybaris, and Dares, and Thersilochus,\nand, slipped from the neck of his rearing horse, Thymoetes.",
 "He sends Asbytes to keep him company, with a cast of his spear. Chloreus too, and Sybaris, Dares and Thersilochus, and Thymoetes, thrown from the neck of his rearing horse.",
 "Greenough prints a full stop after 'mittit', and 363–364 have no verb of their own: the accusatives must still depend on 'mittit' or a verb like it understood. Most texts print a comma, and the stop may be a misprint, but a pause with the verb carried over is possible, so the print is kept and read in that sense. 'Huic comitem… mittit', 'sends (him) as a companion to this man', to the dead Eumedes in the underworld. 'coniecta cuspide', ablative absolute, 'with a hurled point'; consonantal i after the prefix, con-jec-ta. 'Asbyten', 'Chlorea', 'Dareta', 'Thymoeten', Greek accusatives. 'sternacis', 'apt to throw its rider', from 'sterno'. 'lapsum cervice', 'slipped from the neck'. Elision 'comit(em) Asbyten'."),
(367, 'caelo:',
 "And just as when of Edonian Boreas the blast on the deep\nroars, the Aegean, and follows to the shores the swell,\nwhere the winds have leaned down, flight the clouds take in the sky:",
 "And as when the blast of Thracian Boreas roars over the deep Aegean and the swell runs after it to the shore, wherever the winds bear down, the clouds take flight across the sky:",
 "A second simile, of the north wind: 'velut… cum… sic' (368). 'Edoni', 'Edonian', of the Edoni, a Thracian people, so 'Thracian': Boreas, the north wind, lives in Thrace, like Mars in the first simile. 'Boreae', three syllables, Bo-re-ae. 'alto… Aegaeo', 'on the deep Aegean', framing the verb; 'Aegaeo', 'Ae-' one long syllable. 'sequitur… fluctus', 'the swell follows', the sea rising behind the wind. 'qua', 'where'. 'incubuere' = 'incubuerunt', the -ere perfect, 'have leaned upon', of wind pressing on sea and land. 'fugam dant', 'take flight'. 'caelo', ablative of place. Elisions 'sequiturqu(e) ad', 'vent(i) incubuere'."),
(370, 'volantem.',
 "so for Turnus, wherever a way he cuts, the columns give way\nand, turned about, rush the battle-lines; the onrush carries him himself,\nand his crest, against the chariot, shakes the breeze, flying.",
 "so, wherever Turnus cuts his way, the ranks give before him and the lines turn and run; his own momentum carries him on, and the wind that meets the chariot shakes his streaming crest.",
 "'sic', answering 'velut' in 365. 'Turno', dative, 'for Turnus, before Turnus', with 'cedunt', 'give way'. 'quacumque viam secat', 'wherever he cuts a path'. 'conversae… acies', 'the lines turned (in flight)'. 'fert impetus ipsum', 'his own rush carries him', as the wind carries the waves. 'adverso curru', 'with the chariot facing (it)', driving into the wind; 'aura', 'the breeze', is the subject of 'quatit'. 'cristam… volantem', 'the flying crest', framing the line. Elision 'crist(am) adverso'."),
(371, 'frementem:',
 "Did not endure him pressing on, Phegeus, and in spirit raging:",
 "Phegeus could not bear to see him pressing on and roaring in his fury:",
 "'Non tulit', 'did not endure', a phrase for a man who cannot stand by and watch. 'instantem… frementem', 'pressing on… raging', the accusatives describing Turnus, with 'eum' understood. 'animis', 'in spirit', the plural for high temper. 'Phegeus', a Trojan with a Greek name: 'eu' is one syllable, the Greek diphthong, Phe-geus. No elisions."),
(373, 'equorum.',
 "he threw himself before the chariot and, foaming with the bits,\nthe mouths of the speeding horses with his right hand he wrenched aside.",
 "He flung himself in front of the chariot, and with his right hand wrenched aside the heads of the galloping horses, their mouths foaming at the bit.",
 "'obiecit sese ad currum', 'threw himself in the way of the chariot'; 'obiecit' has a consonantal i after the prefix, ob-je-cit, the first syllable long. 'spumantia… ora', 'foaming mouths', the horses' mouths white round the bit; 'frenis', ablative, 'with the bits'. 'citatorum… equorum', 'of the horses driven at speed', framing the line around 'dextra detorsit'. 'detorsit', 'twisted aside', a brave and desperate move. Elisions 'ses(e) ad', 'curr(um) et'."),
(376, 'corpus.',
 "While he is dragged and hangs from the yoke, him, uncovered, the broad\nlance overtakes and bursts, driven in, the double-meshed\ncorselet, and the surface of his body tastes with a wound.",
 "While he is dragged along, hanging from the yoke with his body exposed, Turnus's broad lance catches him, drives in and bursts his corselet of double mail, and with a wound just grazes the surface of his flesh.",
 "'Dum trahitur', 'while he is being dragged', 'dum' with the present. 'iugis', 'from the yoke', plural for singular; its i is consonantal. 'retectum', 'uncovered', his side left open as he clings to the horses. 'lata… lancea', 'the broad lance', Turnus's. 'consequitur', 'overtakes'. 'infixa', 'driven in'. 'bilicem', 'of double thread', a corselet of two-ply mail (from 'licium', a thread). 'summum… corpus', 'the surface of the body'; 'degustat', 'tastes, grazes', a vivid image of the spear taking a sip. 'volnere', Greenough's spelling of 'vulnere'. Elisions 'rumpitqu(e) infixa', 'loric(am) et'."),
(378, 'petebat:',
 "He, though, with shield thrust out, turned toward the enemy,\nwas going and help from the drawn point was seeking:",
 "Even so he turned on his enemy with his shield held out before him, and was coming on, looking for help to his drawn sword:",
 "'Ille', Phegeus. 'tamen', 'nevertheless', wounded as he is. 'clipeo obiecto', ablative absolute, 'his shield held out before him'; 'obiecto' has a consonantal i after the prefix. 'conversus in hostem', 'turned toward the enemy'. 'ibat… petebat', imperfects, 'was going… was seeking', the attempt cut short by what follows. 'ducto mucrone', 'with the point drawn', his sword out. 'auxilium… petebat', 'sought help' from it. Elision 'clipe(o) obiecto'."),
(382, 'harenae.',
 "when the wheel, him headlong, and, by its forward rush driven, the axle\nstruck and poured him out on the ground, and Turnus, following,\nbetween the lowest helmet and the edges of the top of the breastplate\ntook off with his sword the head, and the trunk left to the sand.",
 "when the wheel and the axle, hurtling forward, struck him headlong and flung him to the ground; Turnus followed up, and between the rim of his helmet and the upper edge of his breastplate struck off his head with the sword, and left the trunk lying on the sand.",
 "'cum… impulit', 'when (suddenly) the wheel struck', 'cum' with the indicative after 'ibat', the so-called inverted 'cum', which puts the main event in the subordinate clause. 'praecipitem', 'headlong', proleptic: struck so that he fell headlong. 'procursu concitus axis', 'the axle, driven by its forward rush'. 'effundit… solo', 'pours (him) out on the ground', 'solo' an ablative or dative of place. 'imam inter galeam… et oras', 'between the bottom of the helmet and the edges', the preposition set between; 'thoracis', a Greek word, 'of the breastplate'. 'harenae', dative, 'to the sand'. Elisions 'praecipit(em) et', 'im(am) inter'."),
(386, 'gressus.',
 "And while these deaths on the plains, victorious, deals Turnus,\nmeanwhile Aeneas, Mnestheus and faithful Achates\nand Ascanius with them, in the camp set down, bleeding,\nhis alternate steps on a long spear-point propping.",
 "And while Turnus, victorious, was dealing out these deaths across the plain, Mnestheus and faithful Achates, with Ascanius beside them, had brought Aeneas back to the camp and set him down there, bleeding, leaning on a long spear at every other step.",
 "A new paragraph in Greenough: back to the wounded Aeneas. 'ea… funera', 'these deaths', framing most of the line. 'dum… dat', 'while he deals', 'dum' with the present. 'interea', 'meanwhile', repeating the time already set by 'dum'. 'Aenean', Greek accusative; 'Ae-' one long syllable. 'Mnestheus', two syllables, Mnes-theus, the Greek diphthong eu. 'statuere' = 'statuerunt', 'set (him) down'. 'castris', 'in the camp', ablative of place. 'alternos… gressus', 'his alternate steps', limping on one leg. 'nitentem', 'leaning', with the ablative 'cuspide': the spear serves as a staff. Elisions 'Atqu(e) ea', 'intere(a) Aenean'."),
(390, 'remittant.',
 "He rages, and, the shaft being broken, struggles the weapon\nto tear out, and for help the way, whichever is nearest, demands,\nthat with the sword they cut, broad, the wound, and of the weapon the lurking-place\nlay open deep, and himself to the wars send back.",
 "He rages, and struggles to pull out the weapon whose shaft has snapped, and calls for the nearest way to help: let them cut open the wound with a broad sword, lay bare the arrow's hiding place to its depths, and send him back to the fighting.",
 "'Saevit', 'he rages', in pain and frustration. 'infracta… arundine', ablative absolute, 'the shaft having broken off', so that the head stays in the wound; 'arundine' is Greenough's spelling of 'harundine'. 'luctatur… eripere', 'struggles to pull out', an infinitive with a verb of effort. 'auxilio… viam, quae proxima (est)', 'the way to help that is nearest', 'auxilio' a dative of purpose. 'poscit' is followed by subjunctives without 'ut', 'secent… rescindant… remittant', 'demands (that) they cut… lay open… send back'. 'telique latebram', 'the hiding place of the weapon', where the barb is buried. Elisions 'eriper(e) auxilioque', 'sesequ(e) in'."),
(394, 'sagittas.',
 "And now was at hand, by Phoebus beyond others beloved, Iapyx,\nson of Iasus, to whom once, seized by a keen love,\nhimself his own arts, his own gifts, gladly Apollo\naugury and the lyre was giving, and swift arrows.",
 "And now Iapyx, son of Iasus, was there, whom Phoebus loved above all others; long ago Apollo, gripped by a keen love for him, had gladly offered him his own arts, his own gifts: augury, the lyre, and swift arrows.",
 "'Iamque aderat', 'and now he was there'. 'Phoebo', dative of agent with the participle 'dilectus', 'loved by Phoebus', Apollo. 'Iapyx', three syllables, I-a-pyx, the I a vowel and not consonantal; 'Iasides', 'son of Iasus', a Greek patronymic, likewise beginning with a vowel. 'cui', 'to whom', one syllable. 'acri… captus amore', 'seized by a fierce love'. 'suas artes, sua munera', 'his own arts, his own gifts', in apposition to the three gifts listed in 394. 'dabat', 'was giving', 'offered', the imperfect of an offer not taken up, as the next lines show. 'celeris', Greenough's -is accusative. Elisions 'Iamqu(e) aderat', 'Phoeb(o) ante', 'ant(e) alios'."),
(397, 'artes.',
 "He, so that of his father, laid down, he might put off the fate,\nto know the powers of herbs and the practice of healing\npreferred, and the silent arts to pursue without glory.",
 "But he, to put off the death of his father, who lay given up for lost, chose rather to learn the powers of herbs and the practice of healing, and to follow the silent arts without fame.",
 "'Ille', Iapyx. 'ut… proferret', 'in order to put off', a purpose clause. 'depositi… parentis', 'of his father, laid down', a word for a sick man given up as dying. 'fata', 'the death', plural for a single fate. 'scire… agitare', infinitives with 'maluit', 'preferred to know… to practise'. 'potestates herbarum', 'the powers of herbs', Apollo's own healing art. 'usum medendi', 'the practice of healing', with the gerund. 'mutas… artes', 'silent arts', unsung, unlike prophecy and song, framing the clause. 'inglorius', 'without glory', an adjective for an adverb. Elisions 'herbar(um) usumque', 'agitar(e) inglorius'."),
(400, 'immobilis.',
 "Was standing, bitterly chafing, on a huge spear leaning,\nAeneas, with a great crowding of young men and of grieving Iulus,\nunmoved by tears.",
 "Aeneas stood there leaning on his great spear and chafing bitterly, while the young men and the grieving Iulus thronged round him, and their tears did not move him.",
 "'Stabat… Aeneas', the subject held back to the next line. 'acerba fremens', 'raging bitterly', the neuter plural used as an adverb. 'nixus in hastam', 'leaning on a spear'. 'magno… concursu', 'with a great crowding', ablative of attendant circumstance, framing 'iuvenum et maerentis Iuli'. 'Aeneas', 'Ae-' one long syllable; 'Iuli', three syllables, I-u-li, the I a vowel; 'iuvenum', with consonantal i. 'lacrimis immobilis', 'unmoved by tears', theirs (some take it as 'not moved to tears' himself): he wants only to return to the fight. Elision 'iuven(um) et'."),
(404, 'ferrum.',
 "He, his cloak thrown back,\nin the Paeonian manner, the old man, girded up,\nmany things with healing hand and with Phoebus's potent herbs\nin vain bustles at; in vain the barb with his right hand\nhe works at, and grips with clinging forceps the iron.",
 "The old man, his cloak drawn back and girt up in the fashion of healers, tries one thing after another, all in vain, with his skilled hand and the potent herbs of Phoebus; in vain he works at the arrowhead with his right hand and grips the iron with clinging forceps.",
 "'Ille', Iapyx. 'retorto… amictu', ablative absolute, 'his cloak twisted back', and 'succinctus', 'girded up', to leave his arms free. 'Paeonium in morem', 'in the manner of Paean', the healer of the gods in Homer, so 'like a physician'; 'Pae-' is one long syllable. 'multa… trepidat', 'bustles at many things', 'multa' an inner accusative. 'manu medica', 'with healing hand'. 'nequiquam… nequiquam', 'in vain… in vain', the repetition stressing the failure. 'spicula', 'the point', the barb. 'sollicitat', 'works at, tries to loosen'. 'prensat', 'keeps gripping', a frequentative of 'prendo'. 'tenaci forcipe', 'with gripping forceps'. Elision 'Paeoni(um) in'."),
(407, 'est.',
 "No Fortune guides the way, in nothing its author Apollo\nhelps; and savage on the plains more and more the horror\ngrows thick, and nearer the evil is.",
 "No good fortune shows the way, and Apollo, the author of the art, gives no help at all; and out on the plain the savage terror swells more and more, and the danger draws nearer.",
 "'Nulla viam Fortuna regit', 'no Fortune guides the way', Fortune as a person, but also simply 'no luck'. 'nihil… subvenit', 'helps not at all', 'nihil' an adverbial accusative. 'auctor Apollo', 'Apollo the founder' of medicine, the source of the art, who should help his favourite. 'saevus… horror', 'savage dread', split across the line: the din of battle comes up to the camp. 'magis ac magis', 'more and more'. 'crebrescit', 'grows frequent, thickens', an inceptive verb. 'malum', 'the trouble', the danger: the enemy are coming. Elision 'mal(um) est'."),
(409, 'mediis.',
 "Now with dust the sky\nstand they see: up come the horsemen, and darts in the camp\nthick fall, in its midst.",
 "Already they see the sky stand thick with dust; the horsemen are coming up, and darts are falling thick in the very middle of the camp.",
 "'Iam', 'already'. 'pulvere caelum stare', 'the sky stands with dust', accusative and infinitive with 'vident': 'stare' here means 'stand thick, be clogged', the dust hanging solid in the air. 'subeunt', 'come up', the enemy approaching the camp. 'equites', 'horsemen', the Latin cavalry. 'spicula… densa', 'thick darts', the adjective almost an adverb, 'falling thick'. 'castris… mediis', 'in the midst of the camp', ablative of place, framing 'densa cadunt'. No elisions."),
(410, 'cadentum.',
 "Goes, grim, to the upper air a shout\nof the warring young men and, under harsh Mars, the falling.",
 "A grim cry rises to the sky from the young men fighting and falling under the hard hand of war.",
 "'It… ad aethera', 'goes to the upper air', 'aethera' the Greek accusative of 'aether', with 'Ae-' one long syllable. 'tristis… clamor', 'a grim shout', framing the clause. 'bellantum… cadentum', 'of (men) warring… falling', present participles with the shorter genitive plural in '-um', framing the next line. 'duro sub Marte', 'under harsh Mars', the god's name standing for war. Elision 'iuven(um) et'."),
(415, 'sagittae:',
 "Here Venus, by the undeserved pain of her son shaken,\ndittany, his mother, from Cretan Ida plucks,\na stalk with downy leaves and with a flower tufted,\npurple; not to wild goats unknown is that\nherb, when in their backs the flying arrows have stuck:",
 "At this Venus, his mother, shaken by her son's undeserved pain, plucks dittany from Ida in Crete, a stalk with downy leaves crowned with a purple flower; it is a herb well known to the wild goats when winged arrows have lodged in their backs:",
 "'Hic', 'at this point'. 'indigno… dolore', 'by the undeserved pain', framing the phrase. 'genetrix', 'his mother', stressing why she acts. 'dictamnum', dittany, a plant of the Cretan mountains famed in antiquity for healing wounds; 'Cretaea… Ida', Cretan Ida, not the mountain near Troy. 'puberibus… foliis', 'with downy leaves', ablative of description; 'comantem', 'tufted, crowned'. 'non illa… incognita', 'not unknown', an understatement for 'well known'; 'illa… gramina', plural for a single herb. The belief that wounded wild goats in Crete ate dittany to make arrows drop out is in Aristotle and Theophrastus. 'haesere' = 'haeserunt', the -ere perfect, here of what happens as a rule. No elisions."),
(419, 'panaceam.',
 "this Venus, in a dark cloud her face wrapped,\nbrought down; with this the water poured into the shining basins\nshe tinctures, secretly medicating, and sprinkles health-giving\njuices of ambrosia and fragrant panacea.",
 "This Venus brought down, her face veiled in a dark cloud; with it she secretly steeped the water poured into the gleaming bowls, giving it healing power, and sprinkled in the health-giving juice of ambrosia and fragrant panacea.",
 "'hoc', the dittany. 'obscuro faciem circumdata nimbo', 'her face wrapped in a dark cloud', 'faciem' an accusative of the part with a passive participle, the Greek accusative again; the goddess comes unseen. 'fusum labris… amnem', 'the water (literally 'river') poured into the basins', 'labrum' a basin with a lip; 'splendentibus', 'shining', of bronze. 'inficit', 'dips, steeps'; 'medicans', 'making it medicinal'. 'salubris', Greenough's -is accusative, with 'sucos'. 'ambrosiae', four syllables, am-bro-si-ae, the food of the gods. 'panaceam', four syllables, pa-na-ce-am, the Greek 'all-heal', a healing plant. No elisions."),
(422, 'sanguis;',
 "Bathed with that water the wound long-lived Iapyx,\nnot knowing, and suddenly all from the body fled,\nas you might expect, the pain, all stopped deep in the wound the blood;",
 "Old Iapyx bathed the wound with this water, not knowing what was in it, and suddenly, as might be expected, all the pain fled from the body and all the blood stopped flowing deep in the wound;",
 "'Fovit', 'bathed, fomented', from 'foveo', 'warm', the word for applying warm lotions. 'ea… lympha', 'with that water', 'ea' ablative, two syllables. 'longaevus', 'aged'. 'Iapyx', three syllables, as at 391. 'ignorans', 'unaware' of the goddess's work. 'quippe', 'naturally, of course', placed late: this is what such a remedy would do. 'omnis… dolor… omnis… sanguis', the repetition, 'omnis' nominative singular. 'stetit', 'stood still', stopped. 'imo volnere', 'in the depth of the wound'. 'volnus', 'volnere', Greenough's spellings of 'vulnus', 'vulnere'. Elision 'subitoqu(e) omnis'."),
(424, 'vires.',
 "and now, following the hand, with no one forcing, the arrow\nfell out, and new returned to their former state the strengths.",
 "and now the arrow followed his hand with no force at all and dropped out, and his strength came back, renewed, to what it had been before.",
 "'secuta manum', 'following the hand' of Iapyx, coming out at the lightest touch. 'nullo cogente', ablative absolute, 'with no one forcing (it)'. 'excidit', 'fell out', from 'ex' and 'cado'. 'novae… vires', 'renewed strength', framing the clause. 'rediere' = 'redierunt'. 'in pristina', 'to (their) former state', the neuter plural used as a noun. The healing of a wounded hero by a god is Homeric: Apollo heals Glaucus's arm in Iliad XVI, and Aeneas himself is healed in Apollo's temple in Iliad V. Elision 'redier(e) in'."),
(426, 'hostem.',
 "“Arms, quickly, hurry to the man! Why do you stand?” Iapyx\ncries out, and first the spirits kindles against the enemy.",
 "“Quick, bring the man his arms! Why are you standing there?” shouts Iapyx, and he is the first to fire their courage against the enemy.",
 "The print has 'statis? ”Iapyx', the closing mark set after the space, a misprint for 'statis?” Iapyx', corrected here. 'Arma… properate viro', 'hurry arms to the man', 'properare' with an object, 'bring quickly'; 'citi', 'quick', an adjective for an adverb. 'Quid statis?', 'why do you stand (idle)?'. 'Iapyx', three syllables, as before. 'conclamat', 'shouts aloud'. 'primus… adcendit', 'is the first to kindle'; 'adcendit' is Greenough's spelling of 'accendit'. 'animos', 'spirits, courage'. Elision 'primusqu(e) animos'."),
(429, 'remittit.”',
 "“Not by human means do these things, not by art as mistress\ncome about, nor you, Aeneas, does my right hand save:\na greater one, a god, is at work, and to greater works sends you back.”",
 "“This does not come about by human means or by any mastery of art, and it is not my hand, Aeneas, that saves you: some greater power, a god, is at work, and sends you back to greater deeds.”",
 "Iapyx's words. 'Non haec… non', 'not… not', the repetition. 'humanis opibus', 'by human resources'. 'arte magistra', 'with art as mistress', skill as the guide. 'proveniunt', 'come forth, come about'. 'Aenea', vocative, Greek in form, 'Ae-' one long syllable; 'te' elides before it. 'maior… deus', 'a greater (one), a god'. 'agit', 'is acting', 'is at work'. 'opera ad maiora', 'to greater tasks', 'maior' taken up again. 'remittit', 'sends back', answering Aeneas's own wish at 390. 'maior', 'maiora', with consonantal i, mai-jor. Elisions 't(e) Aenea', 'atqu(e) opera', 'oper(a) ad'."),
(431, 'coruscat.',
 "He, greedy for battle, his calves had shut in gold\non this side and that, and hates delays and brandishes his spear.",
 "Aeneas, hungry for the fight, had already shut his legs in greaves of gold on either side; he hates delay, and makes his spear flash.",
 "'Ille', Aeneas. 'avidus pugnae', 'greedy for battle', the genitive with an adjective of desire. 'suras incluserat auro', 'had enclosed his calves in gold', had put on his golden greaves, part of the armour Vulcan made in Book VIII; the pluperfect shows his speed: it is done before the others can bring the rest. 'hinc atque hinc', 'on this side and on that', both legs. 'odit moras', 'hates delays'. 'coruscat', 'brandishes, makes (it) flash'. Elisions 'Ill(e) avidus', 'atqu(e) hinc'."),
(434, 'fatur:',
 "After, fitted to his side, the shield and the corselet to his back is,\nAscanius, with arms flung round, he embraces,\nand, through the helmet, the tips of kisses tasting, speaks:",
 "Once the shield is fitted to his side and the corselet to his back, he folds Ascanius in his armoured embrace and, kissing him lightly through the helmet, says:",
 "'Postquam… est', 'after the shield (is) fitted to his side', one verb serving both subjects. 'habilis', 'handy, well fitted'. 'fusis circum… armis', 'with his armour poured round (him)': he holds the boy in full armour, though some take 'arma' loosely of his arms. 'summa… oscula', 'the tips of kisses'; 'delibans', 'taking a taste of', a light kiss through the helmet. Compare Hector in Iliad VI, who takes off his helmet to hold his son when the baby shrinks from the plume: Aeneas, already armed for battle, does not. Elisions 'Postqu(am) habilis', 'terg(o) est'."),
(436, 'aliis.',
 "“Learn, boy, manhood from me, and labour that is real,\nfortune from others.",
 "“Learn from me, my boy, what manhood is, and what real labour is; learn about good fortune from others.",
 "The parting speech runs to 440. 'Disce… ex me… ex aliis', 'learn from me… from others', the one verb governing both halves. 'puer', 'boy', affectionate. 'virtutem', 'manhood, courage', from 'vir'. 'verum laborem', 'true labour', the real hardship of a hero's life, not its show. 'fortunam', 'good fortune', which Aeneas has never had: a rueful turn. The model is Ajax's farewell to his son in Sophocles, 'boy, may you prove luckier than your father, and like him in all else' (Ajax 550–551), and behind that Hector's prayer for his son in Iliad VI. Elisions 'virtut(em) ex', 'fortun(am) ex'."),
(437, 'ducet.',
 "Now you my right hand in war\nwill keep defended and among great rewards will lead.",
 "For now my right hand will keep you safe in war and lead you to great rewards.",
 "'Nunc', 'now', set against 'mox' in 438: today he protects the boy; later the boy must act for himself. 'te… defensum dabit', 'will render you defended', 'dare' with a participle meaning 'make, cause to be', 'will see you safe'. 'mea dextera', 'my right hand', the hand that fights. 'magna inter praemia', 'among great rewards', the preposition between adjective and noun: the prizes of victory, a kingdom in Italy. 'ducet', 'will lead'. Elision 'magn(a) inter'."),
(440, 'Hector.”',
 "You, see to it, soon, when ripe your age has grown,\nthat you be mindful, and you, in your mind recalling the examples of your kin,\nboth your father Aeneas and your uncle Hector, may they rouse.”",
 "And you, when before long your years have ripened, make sure that you remember; and as you call to mind the examples of your own people, let your father Aeneas and your uncle Hector stir you on.”",
 "'facito', the future imperative, solemn and lasting, 'see to it'; with 'sis memor', 'that you be mindful', a subjunctive without 'ut'. 'mox cum… adoleverit', 'when soon (your) age has grown ripe', future perfect. 'te… repetentem', 'you, recalling', the object of 'excitet', 'may… rouse'. 'exempla tuorum', 'the examples of your own (people)'. 'et pater Aeneas et avunculus… Hector', 'both your father Aeneas and your uncle Hector', framing the last line; Hector was the brother of Creusa, Ascanius's mother. The singular verb agrees with the nearer subject. 'Aeneas', 'Ae-' one long syllable. Elisions 'matur(a) adoleverit', 't(e) animo', 'repetent(em) exempla'."),
]

# Speech-mark check exemptions (rule 5b), by closing text of the unit: none needed.
#  'hostem.' (425): the print has 'statis? ”Iapyx', closing mark after the space; the mark counts still match,
#      and l and i place it correctly. 'quisquam.' (322-323): the print has 'facti. nec'; l and i read 'facti, nec'.
#  'Thymoeten.' (362-364): the stop after 'mittit' is doubtful, kept as printed, with a note.
EXEMPT = set()
# The long period 353-358 is cut at the comma after 'aperto' (353), as build_aeneid.py allows.
OVERLONG = set()
P = A.part('aeneid-094'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']} | {L[0]['n']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, tail, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG' + (' (known, uncuttable)' if ln in OVERLONG else ''), ln, t.count('\n') + 1, 'lines')
    if '\n' in i: print('NEWLINE IN i', ln)
    if t.rstrip('”]')[-1] not in A.TERMINAL + ',': print('ENDING', ln, repr(t[-12:]))
    nw = len(n.split())
    if nw > 139 or nw < 15: print('NOTE LENGTH', ln, nw)
    for mk in '“”[]':
        if t.count(mk) != l.count(mk) and tail not in EXEMPT: print('MARK l', ln, mk)
        if mk in '“”' and t.count(mk) != i.count(mk) and tail not in EXEMPT: print('MARK i', ln, mk)
    if '“' in n or '”' in n:
        if tail not in EXEMPT and 'The print has' not in n: print('DOUBLE MARK IN n', ln)
covered = sorted({ln + k for (t, ln) in cuts for k in range(t.count('\n') + 1)})
if covered != [l['n'] for l in L]: print('COVERAGE', covered)
joined = '\n'.join(l['t'] for l in L)
rebuilt = ''.join(t + ('\n' if (k + 1 < len(cuts) and cuts[k + 1][1] != ln + t.count('\n')) else ' ' if k + 1 < len(cuts) else '') for k, (t, ln) in enumerate(cuts))
if rebuilt != joined: print('JOIN MISMATCH')
if A.sha(L) != P.get('sha256', A.sha(L)): print('SHA MISMATCH')
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units;', len(covered), 'lines covered')
